// The fictional datasets and the odds the generators draw them by.
//
// The tables are generated by `tools/emit` from the JavaScript package; the
// chances below are written by hand in all three packages, and `tools/parity`
// compares them.

import 'package:randino/src/types.dart';

export 'package:randino/src/fictional/data/avoid.dart';
export 'package:randino/src/fictional/data/compounds.dart';
export 'package:randino/src/fictional/data/kinds.dart';
export 'package:randino/src/fictional/data/names.dart';
export 'package:randino/src/fictional/data/places.dart';
export 'package:randino/src/fictional/data/syllables.dart';

/// How often a place carries its kind when the caller left `includeKind` out,
/// as a percentage per level. A district is nearly always named with one
/// (`Evelyn Bay`), and a country is as often its name alone (`Glacia`) as a
/// kingdom. Internal.
const Map<LocationLevel, int> fictionalKindChance = <LocationLevel, int>{
  LocationLevel.country: 50,
  LocationLevel.region: 50,
  LocationLevel.city: 40,
  LocationLevel.district: 70,
};

/// How often an invented name or place takes a `middle` syllable, as a
/// percentage. Internal.
const int fictionalMiddleChance = 40;

/// How often an invented place is built from syllables (`Silvaria`) rather than
/// from two English halves (`Ravenford`), as a percentage per level. A country
/// is a sweeping Latin name and a city an English town's; a district built from
/// syllables is named like a person (`Kalira Park`). Internal.
const Map<LocationLevel, int> fictionalSyllableChance = <LocationLevel, int>{
  LocationLevel.country: 100,
  LocationLevel.region: 50,
  LocationLevel.city: 0,
  LocationLevel.district: 40,
};
